import {participation,participationBar,openParticipation,refreshParticipationBanners} from './participation.js?v=163b4350cff0';
export const FEEDBACK_ORIGIN='https://manor-feedback.tacocat070116.chatgpt.site';
export const FEEDBACK_STATUSES={open:'의견 수렴',reviewing:'검토 중',planned:'반영 예정',completed:'반영 완료',hold:'보류'};
export const FEEDBACK_STATUS_HELP={
 open:'접수된 의견에 대해 추가 의견을 받는 상태입니다. 반영 여부는 아직 정해지지 않았습니다.',
 reviewing:'제안 내용이나 제보한 문제를 확인하고, 반영할지 판단하는 단계입니다.',
 planned:'반영하기로 결정한 의견입니다. 이 표시만으로 적용 일정이 확정된 것은 아닙니다.',
 completed:'사이트에 변경 사항을 반영한 상태입니다. 적용 내용은 운영자 답변에서 확인해 주세요.',
 hold:'현재 작업을 진행하지 않는 상태입니다. 보류 이유와 다시 검토할 조건은 의견별로 안내합니다.'
};
const statusKey=p=>Object.hasOwn(FEEDBACK_STATUSES,p.status)?p.status:'';
const hasResponse=p=>typeof p.reason==='string'&&p.reason.trim().length>0;
const missingResponse=p=>({reviewing:'구체적인 검토 내용은 아직 등록되지 않았습니다.',planned:'구체적인 반영 내용과 일정은 아직 등록되지 않았습니다.',completed:'구체적인 적용 내용은 아직 등록되지 않았습니다.',hold:'이 의견의 보류 사유는 아직 등록되지 않았습니다.'}[statusKey(p)]||'아직 등록된 운영자 답변이 없습니다.');
export const FEEDBACK_CATEGORIES={feature:'기능 제안',correction:'정보 수정',bug:'오류 제보',design:'디자인'};
export const feedbackEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=feedbackEscape;
const date=t=>new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
const glyph={message:'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8M8 12h5"/>',plus:'<path d="M12 4v16M4 12h16"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',reply:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 7 7v4"/>',check:'<path d="m4 12 5 5L20 6"/>'};
const icon=n=>`<svg class="fb-icon fb-icon-${n}" aria-hidden="true" viewBox="0 0 24 24">${glyph[n]||glyph.message}</svg>`;
const badge=p=>`<span class="fb-status status-${statusKey(p)||'unknown'}">${e(FEEDBACK_STATUSES[statusKey(p)]||'상태 확인 필요')}</span>`;
const options=(dict,value,first='')=>(first?`<option value="">${e(first)}</option>`:'')+Object.entries(dict).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${e(v)}</option>`).join('');
const who=(a,chars,author=false)=>`<span class="fb-person">${chars[a?.characterId]?`<img src="${e(chars[a.characterId].portrait)}" alt="" width="30" height="30" loading="lazy">`:''}<span>${e(a?.name||'장원의 손님')}</span>${author?'<span class="fb-author-label">작성자</span>':''}</span>`;
export function feedbackCard(p,chars){
 const answered=hasResponse(p);
 const responseId=`fb-card-response-${e(p.id)}`;
 return `<a class="fb-card" href="#v=feedback&post=${e(p.id)}" data-fb="open" data-id="${e(p.id)}" aria-labelledby="fb-card-title-${e(p.id)}" aria-describedby="${responseId}"><div class="fb-card-top"><span class="fb-category">${e(FEEDBACK_CATEGORIES[p.category])}</span>${badge(p)}${p.hidden?'<span class="fb-hidden-label">숨김</span>':''}</div><h2 id="fb-card-title-${e(p.id)}">${e(p.title)}</h2><p class="fb-excerpt">${e(p.body)}</p><div class="fb-card-meta">${who(p.author,chars)}<time datetime="${new Date(p.createdAt).toISOString()}">${e(date(p.createdAt))}</time></div><div class="fb-card-answer" id="${responseId}">${answered?`<span class="fb-response-badge">${icon('check')}운영자 답변</span><p>${e(p.reason)}</p>`:`<p class="fb-answer-pending">${e(missingResponse(p))}</p>`}</div><div class="fb-card-bottom"><span class="fb-comment-count">${icon('message')}댓글 ${e(p.commentCount)}</span></div></a>`;
}
export function feedbackStatusGuide(){return `<details class="fb-status-guide"><summary>처리 상태는 어떤 뜻인가요?</summary><dl>${Object.keys(FEEDBACK_STATUSES).map(status=>`<div><dt>${badge({status})}</dt><dd>${e(FEEDBACK_STATUS_HELP[status])}</dd></div>`).join('')}</dl><p>상태는 의견에 따라 달라지며, 순서대로 모두 거치는 것은 아닙니다. 운영자 답변이 있어도 반영이 완료된 것은 아닙니다.</p></details>`;}
export function feedbackProgress(p){return `<section class="fb-progress" aria-labelledby="fb-progress-title"><div><h2 id="fb-progress-title">현재 처리 상태</h2>${badge(p)}</div><p>${e(FEEDBACK_STATUS_HELP[statusKey(p)]||'처리 상태를 확인할 수 없습니다. 운영자 답변과 처리 이력을 확인해 주세요.')}</p>${hasResponse(p)?'':`<p class="fb-answer-pending">${e(missingResponse(p))}</p>`}</section>`;}
export function feedbackComment(c,chars,admin=false){return `<article class="fb-comment ${c.parentId?'is-reply':''}" id="fb-comment-${e(c.id)}"><div class="fb-comment-meta">${who(c.author,chars,c.isAuthor)}<time>${e(date(c.createdAt))}</time></div>${c.replyTo?`<span class="fb-reply-to">${icon('reply')}${e(c.replyTo.name)}에게</span>`:''}<p class="fb-comment-text ${c.deleted||c.hidden?'muted':''}">${e(c.deleted?'삭제된 댓글입니다.':c.hidden&&!admin?'운영자가 숨긴 댓글입니다.':c.body)}</p><div class="fb-comment-actions">${!admin&&!c.deleted&&!c.hidden?`<button type="button" data-fb="reply" data-id="${e(c.id)}">답글</button>`:''}${c.isMine&&!c.deleted?`<button type="button" data-fb="delete-comment" data-id="${e(c.id)}">삭제</button>`:''}${admin&&!c.deleted?`<button type="button" data-fb="hide-comment" data-id="${e(c.id)}">${c.hidden?'다시 공개':'숨기기'}</button>`:''}</div></article>`;}
export function feedbackHistory(history=[]){
 const when=t=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
 return history.length?`<details class="fb-history"><summary>처리 이력 ${history.length}건</summary><ol>${history.map(h=>`<li><div>${badge(h)}<time datetime="${new Date(h.createdAt).toISOString()}">${e(when(h.createdAt))}</time></div></li>`).join('')}</ol></details>`:'';
}
export function feedbackResponse(p,admin=false,editing=false,draft=''){
 if(!admin&&!hasResponse(p))return '';
 return `<section class="fb-response" aria-labelledby="fb-response-heading"><div class="fb-response-heading"><h2 class="fb-operator" id="fb-response-heading">${icon('check')}운영자 답변</h2>${admin&&!editing?`<button class="btn quiet small" type="button" data-fb="edit-response" aria-label="운영자 답변 ${p.reason?'수정':'작성'}">${p.reason?'수정':'답변 작성'}</button>`:''}</div>${admin&&editing?`<form class="fb-response-form" data-fb-form="response"><label for="fb-response-body">답변 내용</label><textarea id="fb-response-body" name="reason" rows="7" maxlength="1500" required placeholder="피드백에 대한 답변을 남겨주세요.">${e(draft)}</textarea><div class="fb-form-bottom"><small>답변을 수정해도 처리 이력은 추가되지 않습니다.</small><div class="fb-response-actions"><button type="button" class="btn quiet small" data-fb="cancel-response">취소</button><button type="submit" class="btn primary small">답변 저장</button></div></div></form>`:p.reason?`<p>${e(p.reason)}</p>`:'<p class="fb-response-empty">아직 등록한 답변이 없습니다.</p>'}</section>`;
}
export function feedbackStatusForm(p){return `<form class="fb-admin-form" data-fb-form="status"><h2>${icon('lock')}처리 상태 관리</h2><p class="fb-admin-help">상태가 바뀌면 태그와 변경 날짜·시간이 처리 이력에 남습니다.</p><div class="fb-status-controls"><label for="fb-admin-status">처리 상태<select id="fb-admin-status" name="status">${options(FEEDBACK_STATUSES,p.status)}</select></label><button type="submit" class="btn primary">상태 저장</button></div><div class="fb-admin-visibility"><button type="button" class="btn quiet small" data-fb="hide-post">${p.hidden?'다시 공개':'게시글 숨기기'}</button></div></form>`;}
const readToken=()=>participation.read();

export function mountFeedback(root,{characters={},postId='',navigate,admin=false,origin=FEEDBACK_ORIGIN}={}){
 let alive=true,busy=false,reply=null,currentPost=null,comments=[],nextAfter=null,nextPage=null,posts=[],filters={sort:'new',status:'',category:'',q:'',mine:''},requestVersion=0,formRequest=crypto.randomUUID();
 let editingResponse=false,responseDraft='',responseRevision=0;
 let authorAtOpen=readToken();
 const controllers=new Set();const prefix='/api/'+(admin?'admin':'feedback');
 const move=id=>{editingResponse=false;responseDraft='';if(navigate){navigate(id);return;}postId=id||'';reply=null;formRequest=crypto.randomUUID();load();};
 const notice=(message,error=false)=>{const n=root.querySelector('.fb-notice');if(n){n.textContent=message;n.classList.toggle('is-error',error);n.hidden=!message;}};
 const frame=content=>{if(!alive)return;root.innerHTML=`<section class="feedback-board ${admin?'is-admin':''}"><div class="fb-notice" role="status" aria-live="polite" hidden></div>${content}</section>`;};
 const loading=()=>frame('<div class="fb-empty" role="status" aria-busy="true"><span class="loading-orbit" aria-hidden="true"></span><p>피드백을 불러오고 있습니다.</p></div>');
 const errorScreen=error=>frame(`<div class="fb-empty"><h2>의견을 불러오지 못했습니다.</h2><p>${e(error.message)}</p><button class="btn primary" type="button" data-fb="reload">다시 시도</button></div>`);
 async function api(path,{method='GET',body,guest=true,authorToken,identityRetry=true}={}){
  const requestToken=admin||!guest?'':(authorToken??readToken());
  const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),15000);
  const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(admin)headers['X-Manor-Admin']='1';else if(requestToken)headers.Authorization='Bearer '+requestToken;
  try{const r=await fetch(origin+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:admin?'same-origin':'omit',cache:'no-store',signal:controller.signal});let data;try{data=await r.json();}catch{throw Error('서버 연결을 확인하고 다시 시도해 주세요.');}if(!r.ok){if(data.code==='visitor_invalid'){const removed=await participation.invalidate(requestToken);if(method==='GET'&&guest&&identityRetry)return api(path,{guest:!removed,identityRetry:false});}const err=Error(data.error||'요청을 처리하지 못했습니다.');err.status=r.status;err.code=data.code;throw err;}if(!admin&&guest&&method==='GET'&&identityRetry&&requestToken!==readToken())return api(path,{guest,identityRetry:false});return data;}catch(error){if(error.name==='AbortError')throw Error('연결 시간이 길어지고 있습니다. 다시 시도해 주세요.');throw error;}finally{clearTimeout(timeout);controllers.delete(controller);}
 }
 async function ensureVisitor(){if(admin)return '';if(authorAtOpen&&authorAtOpen!==readToken())throw Error('다른 창에서 연결된 기록이 바뀌었습니다. 입력한 내용은 유지됩니다. 원래 기록으로 다시 연결하거나 내용을 보관한 뒤 새로고침해 주세요.');const identity=await participation.ensure(()=>api('/api/feedback/visitors',{method:'POST',body:{},guest:false}));authorAtOpen=identity;refreshParticipationBanners();return identity;}
 function heading(){return `<div class="fb-heading"><div><h1>${admin?'피드백 관리':'피드백'}</h1><p>${admin?'처리 상태와 답변은 운영자만 변경할 수 있습니다.':'오류·정보 수정·기능 제안을 남기고, 처리 상태와 운영자 답변을 확인하세요.'}</p></div>${admin?'':`<button class="btn primary" type="button" data-fb="compose">${icon('plus')}의견 남기기</button>`}</div>`;}
 function footer(){return `<div class="fb-guide"><p>${icon('lock')}게시글 안에서 같은 캐릭터 닉네임이 유지됩니다. 댓글로 의견을 나눠주세요.</p><p>처리 상태는 운영자가 직접 결정합니다. 개인정보가 포함된 내용은 올리지 마세요.</p><details><summary>익명 참여 안내</summary><p>글과 답변은 서버에 보관됩니다. 개인 복구 코드를 따로 저장하면 다른 브라우저에서도 작성 기록을 다시 연결할 수 있습니다. 코드와 기존 브라우저 정보가 모두 없으면 자동 복구할 수 없습니다.</p></details></div>`;}
 function listView(data,append=false){
  if(!append)posts=data.posts;else posts=[...posts,...data.posts.filter(p=>!posts.some(x=>x.id===p.id))];nextPage=data.nextPage;
  frame(`${heading()}${admin?'':participationBar()}${admin?'':`<div class="participation-tabs" role="group" aria-label="피드백 보기"><button type="button" data-fb="all-posts" aria-pressed="${!filters.mine}">모든 의견</button><button type="button" data-fb="my-posts" aria-pressed="${filters.mine==='1'}">내 참여 글</button></div>`}<div class="fb-summary">${Object.entries(FEEDBACK_STATUSES).map(([s,label])=>`<button type="button" data-fb="status" data-status="${s}" aria-pressed="${filters.status===s}" class="${filters.status===s?'active':''}"><strong>${data.counts[s]||0}</strong><span>${label}</span>${s==='completed'?icon('check'):''}</button>`).join('')}</div>${feedbackStatusGuide()}<div class="fb-toolbar"><label><span class="visually-hidden">피드백 분류</span><select class="filter-select" data-fb-filter="category">${options(FEEDBACK_CATEGORIES,filters.category,'모든 의견')}</select></label><label><span class="visually-hidden">처리 상태 필터</span><select class="filter-select" data-fb-filter="status">${options(FEEDBACK_STATUSES,filters.status,'모든 상태')}</select></label><label class="fb-sort"><span class="visually-hidden">목록 정렬</span><select class="filter-select" data-fb-filter="sort">${options({new:'최신순',discussed:'댓글순'},filters.sort)}</select></label><form class="fb-search" data-fb-form="search"><input name="query" value="${e(filters.q)}" aria-label="피드백 검색" placeholder="의견 검색" maxlength="100"><button type="submit">검색</button></form></div><div class="fb-results-label">${data.total}개의 의견${filters.q?' · '+e(filters.q):''}</div><div class="fb-list">${posts.length?posts.map(p=>feedbackCard(p,characters)).join(''):`<div class="fb-empty">${icon('message')}<h2>${filters.mine?'연결된 기록의 참여 글이 없습니다.':filters.status||filters.category||filters.q?'조건에 맞는 의견이 없습니다.':'아직 등록된 의견이 없습니다.'}</h2><p>${filters.mine?'전에 작성한 글이 있다면 개인 복구 코드로 기록을 연결해 주세요.':filters.status||filters.category||filters.q?'다른 조건으로 찾아보세요.':'오류나 개선할 점이 있다면 의견을 남겨주세요.'}</p></div>`}</div>${nextPage!==null?'<button class="btn fb-more" type="button" data-fb="more-posts">의견 더 보기</button>':''}${footer()}`);
 }
 async function loadList(append=false){const version=++requestVersion;try{const data=!admin&&filters.mine==='1'&&!readToken()?{posts:[],counts:{},total:0,nextPage:null}:await api(prefix+'/posts?'+new URLSearchParams({...filters,page:String(append?nextPage:0)}));if(!alive||version!==requestVersion)return;listView(data,append);}catch(error){if(alive&&version===requestVersion)errorScreen(error);}}

 function commentForm(alias){return `<form class="fb-comment-form" data-fb-form="comment"><div class="fb-composer-person">${alias?who(alias,characters):'<span>등록하면 랜덤 캐릭터 이름이 배정됩니다.</span>'}</div><div class="fb-reply-target" hidden></div><label class="visually-hidden" for="fb-comment-body">댓글 내용</label><textarea id="fb-comment-body" name="body" rows="3" maxlength="1500" required placeholder="의견을 나눠주세요."></textarea><div class="fb-form-bottom"><small>최대 1,500자</small><button class="btn primary small" type="submit">댓글 등록</button></div></form>`;}
 function detailView(data){
  currentPost=data.post;const p=data.post;
  frame(`<button class="back-link fb-back" type="button" data-fb="back">${icon('back')}피드백 목록</button>${admin?'':participationBar()}<article class="fb-detail"><div class="fb-card-top"><span class="fb-category">${e(FEEDBACK_CATEGORIES[p.category])}</span>${badge(p)}${p.hidden?'<span class="fb-hidden-label">숨김</span>':''}</div><h1>${e(p.title)}</h1><div class="fb-card-meta">${who(p.author,characters,true)}<time>${e(date(p.createdAt))}</time></div><div class="fb-post-body">${e(p.body)}</div><div class="fb-detail-actions"><button class="btn quiet small" type="button" data-fb="share">공유</button>${p.isMine?'<button class="btn quiet small" type="button" data-fb="delete-post">삭제</button>':''}</div></article>${feedbackProgress(p)}<div class="fb-response-slot">${feedbackResponse(p,admin,editingResponse,responseDraft)}</div>${admin?feedbackStatusForm(p):''}${feedbackHistory(data.history)}${feedbackStatusGuide()}<section class="fb-discussion"><h2>댓글 <span data-comment-total>${p.commentCount}</span></h2>${admin?'':commentForm(data.myAlias)}<div class="fb-comments">${comments.map(c=>feedbackComment(c,characters,admin)).join('')||'<p class="fb-empty-comments">아직 댓글이 없습니다. 첫 의견을 남겨주세요.</p>'}</div>${nextAfter!==null?'<button class="btn fb-more" type="button" data-fb="more-comments">댓글 더 보기</button>':''}</section>${footer()}`);
 }
 async function loadDetail(){const version=++requestVersion;try{const [data,thread]=await Promise.all([api(prefix+'/posts/'+postId),api(prefix+'/posts/'+postId+'/comments')]);if(!alive||version!==requestVersion)return;comments=thread.comments;nextAfter=thread.nextAfter;detailView(data);}catch(error){if(alive&&version===requestVersion)errorScreen(error);}}
 function compose(){++requestVersion;formRequest=crypto.randomUUID();frame(`<button class="back-link fb-back" type="button" data-fb="back">${icon('back')}피드백 목록</button><div class="fb-heading"><div><h1>의견 남기기</h1><p>어떤 화면에서 겪은 문제인지, 무엇을 바꾸면 좋을지 적어주세요.</p></div></div>${participationBar()}<form class="fb-compose" data-fb-form="post"><label>의견 분류<select class="filter-select" name="category">${options(FEEDBACK_CATEGORIES,'feature')}</select></label><label>제목<input name="title" minlength="3" maxlength="100" placeholder="한 문장으로 알려주세요." required></label><label>내용<textarea name="body" rows="9" minlength="5" maxlength="4000" placeholder="어떤 점을 바꾸면 좋을까요? 오류라면 발생한 화면과 상황을 함께 적어주세요." required></textarea></label><p class="fb-compose-hint">글을 등록하면 랜덤 캐릭터 닉네임이 배정됩니다. 같은 글의 댓글에서도 이 이름을 사용합니다.</p><div class="fb-form-bottom"><small>최대 4,000자 · 개인정보 입력 금지</small><button class="btn primary" type="submit">의견 등록</button></div></form>`);root.querySelector('[name="title"]')?.focus();}
 async function load(){loading();return postId?loadDetail():loadList();}
 async function action(event){
  const recovery=event.target.closest('[data-participation]');
  if(!admin&&recovery?.dataset.participation==='open'){event.preventDefault();if(busy)return;openParticipation({origin,mode:recovery.dataset.participationView,beforeSwitch:()=>![...root.querySelectorAll('[data-fb-form="post"] input,[data-fb-form="post"] textarea,[data-fb-form="comment"] textarea')].some(n=>n.value.trim())||confirm('입력 중인 내용이 있습니다. 기록을 전환하고 목록을 다시 불러올까요?'),onConnected:()=>{authorAtOpen=readToken();controllers.forEach(c=>c.abort());if(!postId)filters.mine='1';load();}});return;}
  const button=event.target.closest('[data-fb]');if(!button||!root.contains(button))return;const a=button.dataset.fb;
  if(a==='open'){
   if(navigate&&(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||(event.button!==undefined&&event.button!==0)))return;
   event.preventDefault();move(button.dataset.id);return;
  }
  event.preventDefault();if(a==='back'){move('');return;}if(a==='compose'){compose();return;}if(a==='reload'){load();return;}
  if(admin&&['edit-response','cancel-response'].includes(a)){if(busy)return;editingResponse=a==='edit-response';responseDraft=editingResponse?(currentPost.reason||''):'';responseRevision=currentPost.replyRevision;root.querySelector('.fb-response-slot').innerHTML=feedbackResponse(currentPost,true,editingResponse,responseDraft);if(editingResponse)root.querySelector('#fb-response-body')?.focus();return;}
  if(!admin&&(a==='all-posts'||a==='my-posts')){filters.mine=a==='my-posts'?'1':'';loadList();return;}
  if(a==='status'){filters.status=filters.status===button.dataset.status?'':button.dataset.status;loadList();return;}
  if(a==='reply'){const c=comments.find(c=>c.id===button.dataset.id);if(!c)return;reply=c;const target=root.querySelector('.fb-reply-target');target.hidden=false;target.innerHTML=`${e(c.author.name)}에게 답글 <button type="button" data-fb="cancel-reply">취소</button>`;root.querySelector('#fb-comment-body')?.focus();return;}
  if(a==='cancel-reply'){reply=null;root.querySelector('.fb-reply-target').hidden=true;return;}
  if(busy)return;busy=true;button.disabled=true;notice('');
  try{
   if(a==='more-posts')await loadList(true);
   if(a==='more-comments'){const data=await api(prefix+'/posts/'+postId+'/comments?after='+nextAfter);if(alive){comments=[...comments,...data.comments.filter(c=>!comments.some(x=>x.id===c.id))].sort((a,b)=>a.seq-b.seq);nextAfter=data.nextAfter;root.querySelector('.fb-comments').innerHTML=comments.map(c=>feedbackComment(c,characters,admin)).join('');if(nextAfter===null)button.remove();}}
   if(a==='share'){const url='https://tacocat070116.github.io/manor-identity-v/#v=feedback&post='+postId;if(navigator.share)try{await navigator.share({title:currentPost.title,url});}catch(err){if(err.name!=='AbortError')throw err;}else{try{await navigator.clipboard.writeText(url);notice('공유 링크를 복사했습니다.');}catch{notice('공유 링크: '+url);}}}
   if(a==='delete-post'&&confirm('이 피드백을 삭제할까요? 목록과 본문에서 더 이상 표시되지 않습니다.')){await api(prefix+'/posts/'+postId,{method:'DELETE'});if(alive)move('');}
   if(a==='delete-comment'&&confirm('이 댓글을 삭제할까요? 답글은 유지됩니다.')){await api(prefix+'/comments/'+button.dataset.id,{method:'DELETE'});await loadDetail();}
   if(a==='hide-post'&&confirm(currentPost.hidden?'이 피드백을 다시 공개할까요?':'이 피드백과 댓글을 일반 사용자에게 숨길까요?')){await api(prefix+'/posts/'+postId+'/visibility',{method:'PATCH',body:{hidden:!currentPost.hidden}});await loadDetail();}
   if(a==='hide-comment'){const c=comments.find(c=>c.id===button.dataset.id);await api(prefix+'/comments/'+c.id,{method:'PATCH',body:{hidden:!c.hidden}});await loadDetail();}
  }catch(error){if(alive)notice(error.message,true);}finally{busy=false;if(button.isConnected)button.disabled=false;}
 }
 async function submit(event){
  const form=event.target.closest('[data-fb-form]');if(!form||!root.contains(form))return;event.preventDefault();const kind=form.dataset.fbForm,values=new FormData(form);
  if(kind==='search'){filters.q=String(values.get('query')||'');loadList();return;}if(busy||!form.reportValidity())return;
  busy=true;const submit=form.querySelector('[type="submit"]');submit.disabled=true;notice('');
  try{
   if(kind==='post'){const authorToken=await ensureVisitor();const data=await api(prefix+'/posts',{method:'POST',authorToken,body:{title:values.get('title'),body:values.get('body'),category:values.get('category'),requestId:formRequest}});if(alive)move(data.post.id);}
   if(kind==='comment'){const authorToken=await ensureVisitor();const data=await api(prefix+'/posts/'+postId+'/comments',{method:'POST',authorToken,body:{body:values.get('body'),parentId:reply?.id||null,requestId:formRequest}});if(alive){reply=null;formRequest=crypto.randomUUID();form.reset();const newComment=data.comment;if(newComment){comments=[...comments.filter(c=>c.id!==newComment.id),newComment].sort((a,b)=>a.seq-b.seq);root.querySelector('.fb-comments').innerHTML=comments.map(c=>feedbackComment(c,characters,admin)).join('');root.querySelector('.fb-reply-target').hidden=true;root.querySelector('.fb-composer-person').innerHTML=who(newComment.author,characters);const refreshed=await api(prefix+'/posts/'+postId);if(alive){currentPost=refreshed.post;root.querySelector('[data-comment-total]').textContent=currentPost.commentCount;}}else await loadDetail();notice('댓글을 등록했습니다.');if(data.id)root.querySelector('#fb-comment-'+data.id)?.scrollIntoView({block:'nearest'});}}
   if(kind==='response'){
    const data=await api(prefix+'/posts/'+postId+'/reply',{method:'PATCH',body:{reason:values.get('reason'),revision:responseRevision}});
    if(alive){currentPost=data.post;editingResponse=false;responseDraft='';root.querySelector('.fb-response-slot').innerHTML=feedbackResponse(currentPost,true);notice(data.unchanged?'답변 내용이 같습니다.':'답변을 저장했습니다.');}
   }
   if(kind==='status'){const data=await api(prefix+'/posts/'+postId+'/status',{method:'PATCH',body:{status:values.get('status'),revision:currentPost.statusRevision}});await loadDetail();if(alive)notice(data.unchanged?'기존 상태와 같아 새 이력을 추가하지 않았습니다.':'처리 상태를 변경했습니다.');}
  }catch(error){if(alive)notice(error.message,true);}finally{busy=false;if(submit.isConnected)submit.disabled=false;}
 }
 function change(event){const key=event.target.dataset.fbFilter;if(key&&Object.hasOwn(filters,key)){filters[key]=event.target.value;loadList();}}
 function input(event){if(admin&&event.target.id==='fb-response-body')responseDraft=event.target.value;if(event.target.closest('[data-fb-form="post"], [data-fb-form="comment"]')&&!busy)formRequest=crypto.randomUUID();}
 root.addEventListener('click',action);root.addEventListener('submit',submit);root.addEventListener('change',change);root.addEventListener('input',input);load();
 return ()=>{alive=false;++requestVersion;controllers.forEach(c=>c.abort());root.removeEventListener('click',action);root.removeEventListener('submit',submit);root.removeEventListener('change',change);root.removeEventListener('input',input);};
}
